const upsertBillingPlan = `-- name: UpsertBillingPlan :one
INSERT INTO platform.billing_plans
    (code, name, description, interval, features, sort)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (code) DO UPDATE SET
    name        = EXCLUDED.name,
    description = EXCLUDED.description,
    interval    = EXCLUDED.interval,
    features    = EXCLUDED.features,
    sort        = EXCLUDED.sort
RETURNING id
`

type UpsertBillingPlanParams struct {
	Code        string
	Name        string
	Description string
	Interval    string
	Features    []byte
	Sort        int32
}

// Idempotent seed upsert for the built-in plan catalogue.
func (q *Queries) UpsertBillingPlan(ctx context.Context, arg UpsertBillingPlanParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, upsertBillingPlan,
		arg.Code,
		arg.Name,
		arg.Description,
		arg.Interval,
		arg.Features,
		arg.Sort,
	)
	var id uuid.UUID
	err := row.Scan(&id)
	return id, err
}

